const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define geometries for Shanghai and Wuhan
  const shanghai = ee.Geometry.Point([121.4737, 31.2304]).buffer(50000); // 50km buffer
  const wuhan = ee.Geometry.Point([114.2734, 30.5833]).buffer(50000); // 50km buffer

  // Define date range
  const startDate = '2020-04-20';
  const endDate = '2020-05-12';

  // Get NO2 data from Sentinel-5P
  const no2Collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(startDate, endDate)
    .select('tropospheric_NO2_column_number_density');

  // Check collection size
  const collectionSize = no2Collection.size().getInfo();
  console.log(`Total images in period: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("C1");
    return;
  }

  // Calculate mean NO2 for each city
  const meanImage = no2Collection.mean();

  // Get Shanghai stats
  const shanghaiStats = meanImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: shanghai,
    scale: 1000,
    maxPixels: 1e9
  });

  // Get Wuhan stats  
  const wuhanStats = meanImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: wuhan,
    scale: 1000,
    maxPixels: 1e9
  });

  const shanghaiData = shanghaiStats.getInfo();
  const wuhanData = wuhanStats.getInfo();

  const shanghaiMean = shanghaiData.tropospheric_NO2_column_number_density;
  const shanghaiPixels = shanghaiData.tropospheric_NO2_column_number_density_count;
  const wuhanMean = wuhanData.tropospheric_NO2_column_number_density;
  const wuhanPixels = wuhanData.tropospheric_NO2_column_number_density_count;

  console.log(`Shanghai - Mean NO2: ${shanghaiMean?.toFixed(6)}, Pixels: ${shanghaiPixels}`);
  console.log(`Wuhan - Mean NO2: ${wuhanMean?.toFixed(6)}, Pixels: ${wuhanPixels}`);

  // Check for no valid pixels
  if (shanghaiPixels === 0 || wuhanPixels === 0) {
    console.log("C2");
    return;
  }

  // Check for invalid results
  if (shanghaiMean === null || wuhanMean === null || 
      isNaN(shanghaiMean) || isNaN(wuhanMean)) {
    console.log("C3");
    return;
  }

  // Compare means and output answer
  if (shanghaiMean > wuhanMean) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
